/* ΦΩΤΟΓΡΑΦΙΑ ΑΝΑΦΟΡΑΣ — το μπλοκ «κενά ρύθμισης» ΠΡΙΝ το T-PROFILE-01.
 *
 * ΓΙΑΤΙ ΥΠΑΡΧΕΙ: η αλλαγή T-PROFILE-01 αγγίζει κώδικα που κρίνει 65 ΖΩΝΤΑΝΟΥΣ
 * αγρούς. Η υπόσχεση είναι ότι για όποιον ΔΕΝ δήλωσε σκοπό η έξοδος μένει
 * ΤΑΥΤΟΣΗΜΗ. Υπόσχεση χωρίς μετρητή είναι ευχή — εδώ είναι ο μετρητής.
 *
 * Αντιγράφηκε ΑΥΤΟΥΣΙΟ από το commit 667664b, πριν την αλλαγή.
 * ΜΗΝ ΤΟ ΠΕΙΡΑΖΕΙΣ: αν αλλάξει, η δοκιμή μη-παλινδρόμησης παύει να αποδεικνύει
 * οτιδήποτε — θα συγκρίνει την αλλαγή με τον εαυτό της.
 */
export const OLD_GAP_BLOCK = "const _gapF = [];\n          {\n            const _ar = Number(fieldConfig?.area);\n            if (!Number.isFinite(_ar) || _ar <= 0) _gapF.push('έκταση');\n            else if (_ar < 20) _gapF.push('έκταση ' + _ar + ' m²;');\n            if (!(Number(fieldConfig?.total_plants) > 0)\n              && !crops.some(c4 => Number(c4?.plants) > 0)) _gapF.push('πλήθος φυτών');\n            /* ══ T-IRRGEOM-GAP-01 (v50.129 · μητρώο #80) ════════════════\n               Ο έλεγχος κοίταζε ΜΟΝΟ το επίπεδο αγρού, ενώ ο ΑΜΕΣΩΣ ΑΠΟ\n               ΠΑΝΩ έλεγχος για το πλήθος φυτών δεχόταν ήδη δήλωση ανά\n               καλλιέργεια. Από την v11 του setFieldParameters\n               (T-CROPKEYS-02) η γεωμετρία ΑΝΑ ΚΑΛΛΙΕΡΓΕΙΑ φτάνει\n               πραγματικά εδώ· χωρίς αυτή τη διόρθωση ο πυρήνας θα\n               ΧΡΗΣΙΜΟΠΟΙΟΥΣΕ την τιμή για τη δόση και ΤΑΥΤΟΧΡΟΝΑ θα\n               έλεγε στον αγρότη «λείπει».\n\n               Η ΕΝΕΡΓΗ τιμή υπολογίζεται ΟΠΩΣ ΑΚΡΙΒΩΣ την υπολογίζει η\n               δόση: `cropParams = {...fieldConfig, ...cropExtras}` —\n               δηλαδή η τιμή της καλλιέργειας όταν υπάρχει, αλλιώς του\n               αγρού. Έτσι μια μερική δήλωση (π.χ. αποστάσεις σταλακτών\n               ανά καλλιέργεια, αποστάσεις γραμμών στον αγρό) μετράει\n               σωστά ως πλήρης.\n\n               ΓΙΑΤΙ every ΚΑΙ ΟΧΙ some (σε αντίθεση με το πλήθος φυτών):\n               η γεωμετρία είναι ΠΑΡΑΚΑΜΨΗ ανά καλλιέργεια. Αν τη δηλώσει\n               ΜΙΑ από τέσσερις, οι άλλες τρεις πέφτουν στο επίπεδο αγρού\n               που εξακολουθεί να λείπει — το κενό ΥΠΑΡΧΕΙ και πρέπει να\n               ειπωθεί. Καλύπτεται μόνο όταν ΚΑΘΕ καλλιέργεια έχει και τα\n               δύο, με τον παραπάνω κανόνα.\n\n               ΣΗΜΕΡΑ Η ΕΞΟΔΟΣ ΕΙΝΑΙ ΤΑΥΤΟΣΗΜΗ με την προηγούμενη: καμία\n               καλλιέργεια δεν έχει ακόμη δικές της τιμές, άρα η ενεργή\n               τιμή ΕΙΝΑΙ η τιμή του αγρού. */\n            if (fieldConfig?.irrigation_system === 'dripIrrigation') {\n              const _geomEff = (c5, k5) => (Number(c5?.[k5]) > 0\n                ? Number(c5[k5]) : Number(fieldConfig?.[k5]));\n              const _geomOk = (c5) => _geomEff(c5, 'irrig_emitter_spacing_m') > 0\n                                   && _geomEff(c5, 'irrig_row_spacing_m') > 0;\n              const _geomCovered = crops.length > 0\n                ? crops.every((c5) => _geomOk(c5))\n                : _geomOk(null);\n              if (!_geomCovered) _gapF.push('γεωμετρία στάγδην');\n            }\n            if (!fieldConfig?.irrigation_system) _gapF.push('σύστημα άρδευσης');\n            if (!fieldConfig?.soil_type && !fieldConfig?.soil_texture_class) _gapF.push('τύπος εδάφους');\n            if (!crops.length) _gapF.push('καμία καλλιέργεια');\n          }";
